#!/usr/bin/env pwsh
# Generated by Claude Opus 4.8 (claude.ai/code) · 2026-11-16

<#
.SYNOPSIS
  Archive recipe (restic): snapshot the backup set into a restic repository.
.DESCRIPTION
  An archiver recipe. The engine passes a RecipeContext and runs its 'archive'
  step against the completed set in $ctx.OutDir (the service's stage dir). It runs
  `restic backup` so the repo stores only the night's changed blocks (dedup), then
  reports the snapshot id back through $ctx.State.Result.

  Retention (GFS) is NOT done here: `restic forget --prune` runs out of band on its
  own schedule (exclusive, off the backup window) — see help/archiving-restic.md.
  This recipe only ever adds snapshots, so a failed or slow prune can never delete a
  backup mid-run.

  Pair with "publishToReady": false in config: the restic repo IS the archive, so
  no local copy is kept in ready/. (A failed snapshot writes no service.archived
  event, so coverage leaves the service overdue and the next window retries it.)

  Env (via $ctx):
    RESTIC_REPOSITORY        (required) repo location (a path, or a backend URL).
    RESTIC_PASSWORD_FILE     file holding the repo password (or set RESTIC_PASSWORD).
    RESTIC_COMPRESSION       restic compression mode (e.g. max); feed uncompressed input.
    RESTIC_HOST              snapshot host tag (default: this machine's hostname).
    RESTIC_TAGS              extra tags, ';'-separated (the service name is always a tag).
    RESTIC_MIN_INTERVAL_HOURS coverage interval for the overdue query (default 24).
    RESTIC_BIN               restic executable (default: restic; overridable for tests).
  Any other RESTIC_* in the env is passed through to the restic process, so backend
  credentials/options work without recipe changes.

  Reports { snapshot; repo; host } back through $ctx.State.Result.
#>

param($Recipe)

if ($null -eq $Recipe) {
    Write-Host 'This is a sequencer recipe; it is loaded by the engine, not run directly.'
    return
}

$Recipe.AddStep('archive', {
    param($ctx)
    $repo = $ctx.RequireEnv('RESTIC_REPOSITORY')
    $bin = $ctx.EnvValue('RESTIC_BIN', 'restic')
    $resticHost = $ctx.EnvValue('RESTIC_HOST', [System.Net.Dns]::GetHostName())
    $passwordFile = $ctx.EnvValue('RESTIC_PASSWORD_FILE', '')
    $compression = $ctx.EnvValue('RESTIC_COMPRESSION', '')
    $extraTags = @($ctx.EnvValue('RESTIC_TAGS', '') -split ';' | ForEach-Object { $_.Trim() } | Where-Object { $_ })

    # snapshot the complete artifact set from the stage dir; dedup stores only the delta
    $resticArgs = @('backup', $ctx.OutDir, '--json', '-r', $repo, '--host', $resticHost, '--tag', $ctx.Service)
    foreach ($t in $extraTags) { $resticArgs += @('--tag', $t) }
    if ($passwordFile) { $resticArgs += @('--password-file', $passwordFile) }
    if ($compression) { $resticArgs += @('--compression', $compression) }

    # pass any other RESTIC_* through to the process so advanced backends work; restore after
    $restore = @{}
    $passed = @()
    if ($null -ne $ctx.Env) {
        foreach ($p in @($ctx.Env.PSObject.Properties)) {
            if ($p.Name -like 'RESTIC_*' -and $p.Name -ne 'RESTIC_BIN') {
                $restore[$p.Name] = [Environment]::GetEnvironmentVariable($p.Name)
                Set-Item -Path "Env:$($p.Name)" -Value ([string]$p.Value)
                $passed += $p.Name
            }
        }
    }

    try {
        $output = & $bin @resticArgs 2>&1
        $code = $LASTEXITCODE
        if ($code -ne 0) {
            throw "restic backup failed (exit $code): $(@($output) -join "`n")"
        }
    }
    finally {
        foreach ($k in $passed) {
            if ($null -eq $restore[$k]) { Remove-Item -Path "Env:$k" -ErrorAction SilentlyContinue }
            else { Set-Item -Path "Env:$k" -Value $restore[$k] }
        }
    }

    # the summary line of restic --json carries the new snapshot id
    $snapshotId = ''
    foreach ($line in @($output)) {
        $text = "$line"
        if ($text -match '"message_type"\s*:\s*"summary"') {
            try {
                $obj = $text | ConvertFrom-Json
                if ($obj.PSObject.Properties['snapshot_id'] -and $obj.snapshot_id) { $snapshotId = [string]$obj.snapshot_id }
            }
            catch { }
        }
    }

    $ctx.State['Result'] = @{ snapshot = $snapshotId; repo = $repo; host = $resticHost }
})

# preflight (before any downtime): the repo, a password source, and the restic
# binary must all be resolvable, or the snapshot is doomed. Catches the classic
# "password file does not exist" that would otherwise fail only after the backup ran.
$Recipe.SetValidate({
    param($ctx)
    $problems = @()
    if (-not $ctx.EnvValue('RESTIC_REPOSITORY', '')) { $problems += 'RESTIC_REPOSITORY not set' }
    $pf = $ctx.EnvValue('RESTIC_PASSWORD_FILE', '')
    if ($pf) {
        if (-not (Test-Path -LiteralPath $pf)) { $problems += "RESTIC_PASSWORD_FILE missing: $pf" }
    }
    elseif (-not $ctx.EnvValue('RESTIC_PASSWORD', '')) {
        $problems += 'no repo password (set RESTIC_PASSWORD_FILE or RESTIC_PASSWORD)'
    }
    $bin = $ctx.EnvValue('RESTIC_BIN', 'restic')
    if (-not (Get-Command $bin -ErrorAction SilentlyContinue)) { $problems += "restic not found: $bin" }
    return $problems
})

# overdue query (plan time): restic retention is out of band, so coverage here is a
# simple minimum interval — covered if the newest snapshot is younger than
# RESTIC_MIN_INTERVAL_HOURS (default 24). overdue = newest age / that interval.
$Recipe.SetOverdue({
    param($ctx)
    $minHours = [double]($ctx.EnvValue('RESTIC_MIN_INTERVAL_HOURS', '24'))
    if ($minHours -le 0) { $minHours = 24 }
    $mine = @($ctx.ReadEvents() | Where-Object {
            $_.type -eq 'service.archived' -and $_.svc -eq $ctx.Service -and $_.PSObject.Properties['ts']
        })
    if (-not $mine) { return 1e6 }   # never archived -> very overdue
    $newest = ($mine | Sort-Object { [datetime]$_.ts } | Select-Object -Last 1)
    $ageSeconds = ($ctx.Now - [datetime]$newest.ts).TotalSeconds
    if ($ageSeconds -lt 0) { $ageSeconds = 0 }
    return $ageSeconds / ($minHours * 3600.0)
})
